// itx16Net runs the DCT16 network form for n nonzero inputs (4, 8 or 16).
func itx16Net(n int, in *[16]archsimd.Int16x16, out *[16]archsimd.Int16x16) {
	switch {
	case n <= 4:
		itx16NetLow4(in, out)
	case n <= 8:
		itx16NetLow8(in, out)
	default:
		itx16NetFull(in, out)
	}
}

