	t17a = itx16Rot(t30, t17, p799, m4017, 12)
	t30a = itx16Rot(t30, t17, p4017, p799, 12)
	t18a = itx16Rot(t29, t18, m4017, m799, 12)
	t29a = itx16Rot(t29, t18, p799, m4017, 12)
	p1703, m1703, p1138, m1138 := k(itx16Kp1703), k32(itx32Km1703), k(itx16Kp1138), k(itx16Km1138)
	t21a = itx16Rot(t26, t21, p1703, m1138, 11)
	t26a = itx16Rot(t26, t21, p1138, p1703, 11)
	t22a = itx16Rot(t25, t22, m1138, m1703, 11)
	t25a = itx16Rot(t25, t22, p1703, m1138, 11)

	t16a = t16.AddSaturated(t19)
