	t19a = t16.SubSaturated(t19)
	t20a = t23.SubSaturated(t20)
	t21 = t22a.SubSaturated(t21a)
	t22 = t22a.AddSaturated(t21a)
	t23a = t23.AddSaturated(t20)
	t24a = t24.AddSaturated(t27)
