// itx32Net runs the DCT32 network form for n nonzero inputs (8, 16 or 32).
func itx32Net(n int, in *[32]archsimd.Int16x16, out *[32]archsimd.Int16x16) {
	switch {
	case n <= 8:
		itx32Low8Net((*[8]archsimd.Int16x16)(in[:8]), out)
	case n <= 16:
		itx32Low16Net((*[16]archsimd.Int16x16)(in[:16]), out)
	default:
		itx32FullNet(in, out)
	}
}

