// itx64Net is inverseDCT64 on sixteen lanes for n nonzero inputs (8, 16 or
// 32): in[k] is coefficient k, out[r] is output r.
func itx64Net(n int, in *[32]archsimd.Int16x16, out *[64]archsimd.Int16x16) {
	var ev [32]archsimd.Int16x16
	var o [32]archsimd.Int16x16
	switch {
	case n <= 8:
		var e [8]archsimd.Int16x16
		e[0], e[1], e[2], e[3] = in[0], in[2], in[4], in[6]
		itx32Low8Net(&e, &ev)
		itx64Odd8(in, &o)
	case n <= 16:
		var e [8]archsimd.Int16x16
		for k := 0; k < 8; k++ {
			e[k] = in[2*k]
		}
		itx32Low8Net(&e, &ev)
		itx64Odd16(in, &o)
	default:
		var e [16]archsimd.Int16x16
		for k := 0; k < 16; k++ {
			e[k] = in[2*k]
		}
		itx32Low16Net(&e, &ev)
		itx64Odd32(in, &o)
	}
	for i := 0; i < 32; i++ {
		out[i] = ev[i].AddSaturated(o[31-i])
		out[63-i] = ev[i].SubSaturated(o[31-i])
	}
	archsimd.ClearAVXUpperBits()
}

